import 'package:flutter/material.dart';
import '../game/platformer_game.dart';
class TouchControls extends StatelessWidget { const TouchControls({super.key, required this.game}); final PlatformerGame game;
  Widget _button({required String label, required VoidCallback down, required VoidCallback up, Color color = const Color(0xff174b65)}) => GestureDetector(onTapDown: (_) => down(), onTapUp: (_) => up(), onTapCancel: up, child: Container(width: 66, height: 66, decoration: BoxDecoration(color: color.withOpacity(.9), shape: BoxShape.circle, border: Border.all(color: Colors.white70, width: 2)), child: Center(child: Text(label, style: const TextStyle(color: Colors.white, fontSize: 25, fontWeight: FontWeight.bold)))));
  @override Widget build(BuildContext context) => Positioned(left: 18, right: 18, bottom: 24, child: SafeArea(child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Row(children: [_button(label: '◀', down: () => game.setLeft(true), up: () => game.setLeft(false)), const SizedBox(width: 12), _button(label: '▶', down: () => game.setRight(true), up: () => game.setRight(false))]), Row(children: [_button(label: '✦', color: const Color(0xff9d3d75), down: game.attack, up: () {}), const SizedBox(width: 12), _button(label: '↑', color: const Color(0xffe5394f), down: () => game.setJump(true), up: () => game.setJump(false))])])));
}
